css:
.page {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 16px;
  align-items: start;
  padding: 16px;
  font-family: system-ui, sans-serif;
}

.column {
  container-type: inline-size;
  container-name: column;
}

.stat {
  container-type: inline-size;
  max-width: 300px;
  padding: 12px;
  border: 1px solid #f97316;
  border-radius: 8px;
  background-color: #fff7ed;
}

.stat-list {
  display: grid;
  gap: 8px;
}

.figure {
  padding: 8px;
  border-radius: 6px;
  background-color: #fed7aa;
  font-weight: 700;
  text-align: center;
}

@container column (min-width: 360px) {
  .stat-list {
    grid-template-columns: repeat(3, 1fr);
  }
}
